const HTML = `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1">
<title>던바튼 오목</title><style>
*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:#f2ead7;color:#29251f;text-align:center}
.wrap{max-width:620px;margin:auto;padding:18px}.card{background:#fffaf0;border:2px solid #6f5a3b;border-radius:18px;padding:16px;box-shadow:0 5px 0 #c7b48f}
h1{margin:4px 0 12px}.row{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}input,button{font:inherit;padding:12px;border-radius:12px;border:1px solid #8b7655}
input{min-width:0;flex:1}button{background:#59472e;color:white;font-weight:700}.sub{background:#8b7655}.hide{display:none}
#board{width:min(94vw,560px);aspect-ratio:1;background:#d7a95e;border:3px solid #5b4020;margin:14px auto;display:grid;grid-template-columns:repeat(15,1fr);padding:9px}
.cell{position:relative;border-right:1px solid #6d4b20;border-bottom:1px solid #6d4b20;min-width:0}.stone{position:absolute;width:88%;height:88%;left:56%;top:56%;transform:translate(-50%,-50%);border-radius:50%;display:grid;place-items:center;font-size:clamp(10px,3vw,20px);font-weight:900;border:2px solid #382b1c;z-index:2}
.s1{background:#e88632}.s2{background:#57b7c8}.s3{background:#e2bd46}.s4{background:#303844;color:#fff}
#status{font-weight:800;margin:10px}.code{font-size:1.25em;font-weight:900;letter-spacing:2px}.small{font-size:.9em;opacity:.75}
</style></head><body><div class="wrap">
<div id="lobby" class="card"><h1>던바튼 오목</h1><p class="small">닉네임을 정하고 친구와 실시간 대전</p>
<div class="row"><input id="nick" maxlength="12" placeholder="닉네임"></div><br>
<div class="row"><button onclick="createRoom()">방 만들기</button><input id="roomCode" maxlength="6" placeholder="방 코드"><button class="sub" onclick="joinRoom()">입장</button></div></div>
<div id="game" class="card hide"><div>방 코드 <span id="code" class="code"></span></div><div id="status">연결 중...</div><div id="players"></div><div id="board"></div>
<div class="row"><button onclick="rematch()">재대전</button><button class="sub" onclick="location.reload()">로비로</button></div></div>
</div><script>
let ws=null, myId=crypto.randomUUID(), state=null;
const chars=["","/f1.jpg","/f2.jpg","/f3.jpg","/f4.jpg"];
function nick(){let n=document.getElementById("nick").value.trim(); if(!n)n="밀레시안"; localStorage.nick=n; return n}
document.getElementById("nick").value=localStorage.nick||"";
function randomCode(){return Math.random().toString(36).slice(2,8).toUpperCase()}
function createRoom(){connect(randomCode())}
function joinRoom(){let c=document.getElementById("roomCode").value.trim().toUpperCase();if(c.length<4)return alert("방 코드를 입력해줘");connect(c)}
function connect(code){
 document.getElementById("lobby").classList.add("hide");document.getElementById("game").classList.remove("hide");document.getElementById("code").textContent=code;
 let proto=location.protocol==="https:"?"wss":"ws"; ws=new WebSocket(proto+"://"+location.host+"/room/"+encodeURIComponent(code));
 ws.onopen=()=>ws.send(JSON.stringify({type:"join",id:myId,name:nick()}));
 ws.onmessage=e=>{let m=JSON.parse(e.data);if(m.type==="state"){state=m.state;render()}else if(m.type==="error")alert(m.message)};
 ws.onclose=()=>document.getElementById("status").textContent="상대 또는 서버 연결이 끊어졌습니다.";
}
function render(){
 let me=state.players.find(p=>p.id===myId), turn=state.players[state.turn];
 document.getElementById("players").innerHTML=state.players.map(p=>"<span><img src=\""+chars[p.char]+"\" style=\"width:32px;height:32px;border-radius:50%;object-fit:cover;vertical-align:middle;border:2px solid #6f5a3b\"> "+p.name+"</span>").join(" &nbsp; VS &nbsp; ");
 let s=state.status==="waiting"?"상대방을 기다리는 중...":state.status==="won"?(state.winner===myId?"승리!":"패배"):(turn?.id===myId?"내 차례":"상대 차례");
 document.getElementById("status").textContent=s;
 let b=document.getElementById("board");b.innerHTML="";
 for(let i=0;i<225;i++){let c=document.createElement("div");c.className="cell";c.onclick=()=>move(i);let v=state.board[i];if(v){let d=document.createElement("div");d.className="stone s"+state.players[v-1].char;let im=document.createElement("img");im.src=chars[state.players[v-1].char];im.style.cssText="width:100%;height:100%;object-fit:cover;border-radius:50%";d.appendChild(im);c.appendChild(d)}b.appendChild(c)}
}
function move(i){if(ws?.readyState===1)ws.send(JSON.stringify({type:"move",index:i,id:myId}))}
function rematch(){if(ws?.readyState===1)ws.send(JSON.stringify({type:"rematch",id:myId}))}
</script></body></html>`;

export default {
 async fetch(request, env) {
   const u=new URL(request.url);
   const FACE_IMAGES={"/f1.jpg":"","/f2.jpg":"","/f3.jpg":"","/f4.jpg":""};
   if(FACE_IMAGES[u.pathname]){
     const bin=Uint8Array.from(atob(FACE_IMAGES[u.pathname]),c=>c.charCodeAt(0));
     return new Response(bin,{headers:{"content-type":"image/jpeg","cache-control":"public,max-age=86400"}});
   }
   if(u.pathname==="/health") return Response.json({ok:true,name:"Dunbarton Omok Online V2"});
   if(u.pathname==="/api/create") return Response.json({code:Math.random().toString(36).slice(2,8).toUpperCase()});
   if(u.pathname.startsWith("/room/")){
     const code=u.pathname.split("/")[2]?.toUpperCase();
     if(!code)return new Response("bad room",{status:400});
     return env.GAME_ROOM.get(env.GAME_ROOM.idFromName(code)).fetch(request);
   }
   return new Response(HTML,{headers:{"content-type":"text/html;charset=UTF-8","cache-control":"no-store"}});
 }
};

export class GameRoom {
 constructor(ctx,env){this.ctx=ctx;this.sessions=new Map();this.state={players:[],board:Array(225).fill(0),turn:0,status:"waiting",winner:null,rematch:[]}}
 async fetch(request){
   if(request.headers.get("Upgrade")!=="websocket")return new Response("WebSocket required",{status:426});
   const pair=new WebSocketPair(), client=pair[0], server=pair[1];server.accept();
   this.sessions.set(server,null);
   server.addEventListener("message",e=>this.message(server,e.data));
   server.addEventListener("close",()=>this.leave(server));
   server.addEventListener("error",()=>this.leave(server));
   return new Response(null,{status:101,webSocket:client});
 }
 message(ws,data){
   let m;try{m=JSON.parse(data)}catch{return}
   if(m.type==="join"){
     if(this.state.players.length>=2 && !this.state.players.some(p=>p.id===m.id)){ws.send(JSON.stringify({type:"error",message:"방이 가득 찼습니다."}));ws.close();return}
     let p=this.state.players.find(p=>p.id===m.id);
     if(!p){const used=this.state.players.map(x=>x.char);let pool=[1,2,3,4].filter(x=>!used.includes(x));p={id:m.id,name:String(m.name||"밀레시안").slice(0,12),char:pool[Math.floor(Math.random()*pool.length)]};this.state.players.push(p)}
     this.sessions.set(ws,m.id);
     if(this.state.players.length===2&&this.state.status==="waiting"){this.state.status="playing";this.state.turn=Math.floor(Math.random()*2)}
     this.broadcast(); return;
   }
   if(m.type==="move"){
     if(this.state.status!=="playing"||this.state.players.length!==2)return;
     let pi=this.state.players.findIndex(p=>p.id===m.id), i=Number(m.index);
     if(pi!==this.state.turn||!Number.isInteger(i)||i<0||i>=225||this.state.board[i])return;
     this.state.board[i]=pi+1;
     if(this.win(i,pi+1)){this.state.status="won";this.state.winner=m.id}else this.state.turn=1-pi;
     this.broadcast();return;
   }
   if(m.type==="rematch"){
     if(!this.state.players.some(p=>p.id===m.id))return;
     if(!this.state.rematch.includes(m.id))this.state.rematch.push(m.id);
     if(this.state.players.length===2&&this.state.rematch.length===2){
       this.state.board=Array(225).fill(0);this.state.winner=null;this.state.rematch=[];this.state.status="playing";this.state.turn=Math.floor(Math.random()*2);
       let a=[1,2,3,4].sort(()=>Math.random()-.5);this.state.players[0].char=a[0];this.state.players[1].char=a[1];
     }this.broadcast();
   }
 }
 win(i,v){let r=Math.floor(i/15),c=i%15;for(const [dr,dc] of [[1,0],[0,1],[1,1],[1,-1]]){let n=1;for(const s of [-1,1]){let rr=r+dr*s,cc=c+dc*s;while(rr>=0&&rr<15&&cc>=0&&cc<15&&this.state.board[rr*15+cc]===v){n++;rr+=dr*s;cc+=dc*s}}if(n>=5)return true}return false}
 leave(ws){let id=this.sessions.get(ws);this.sessions.delete(ws);if(id&&!Array.from(this.sessions.values()).includes(id)){this.state.players=this.state.players.filter(p=>p.id!==id);this.state.board=Array(225).fill(0);this.state.status="waiting";this.state.winner=null;this.state.rematch=[];this.state.turn=0}this.broadcast()}
 broadcast(){let msg=JSON.stringify({type:"state",state:this.state});for(const ws of this.sessions.keys())try{ws.send(msg)}catch{}}
}